import 'dart:ui' show ImageFilter;

import 'package:flutter/material.dart';
import 'package:klunki/l10n/app_localizations.dart';
import 'package:klunki_engine/klunki_engine.dart' as qe show Card, QuartettDeck;
import 'package:url_launcher/url_launcher.dart' as launcher;

import 'quartett_media_data.dart';

/// Photos and Wikipedia links of the Quartett cards (KLD-082).
///
/// The data ([quartettMediaData]) is generated by
/// `tool/fetch_card_media.py` from `assets/quartett/<deck>/credits.json`.
/// Photos are bundled assets (~480 px JPEGs from Wikimedia Commons, free
/// licences only); nothing is loaded from Wikimedia at runtime. Only the
/// Wikipedia, licence and source links need the internet.

/// The credit of a bundled card photo.
@immutable
class QuartettImageCredit {
  /// Asset path, e.g. `assets/quartett/rockets/A1.jpg`.
  final String asset;

  /// The file page on Wikimedia Commons.
  final String source;
  final String author;

  /// Licence short name as on Commons ("CC BY-SA 4.0", "Public domain").
  final String license;
  final String licenseUrl;

  /// A share-alike licence: the resized copy stays under the same licence.
  final bool shareAlike;

  const QuartettImageCredit({
    required this.asset,
    required this.source,
    required this.author,
    required this.license,
    required this.licenseUrl,
    this.shareAlike = false,
  });
}

/// Wikipedia links (German / English article) and photo of one card.
@immutable
class QuartettCardMedia {
  final String? wikiDe;
  final String? wikiEn;
  final QuartettImageCredit? image;
  const QuartettCardMedia({this.wikiDe, this.wikiEn, this.image});

  /// The article in [languageCode] if there is one, else English, else German.
  String? wikipediaUrl(String languageCode) => switch (languageCode) {
    'de' => wikiDe ?? wikiEn,
    _ => wikiEn ?? wikiDe,
  };
}

/// Media of [card] (null: none collected for its deck yet).
QuartettCardMedia? quartettMediaOf(qe.Card card) => quartettMediaData[card.deck]?[card.id];

/// Opens [uri] outside the app (web: a new tab). Returns false on failure.
typedef QuartettLinkOpener = Future<bool> Function(Uri uri);

Future<bool> _launch(Uri uri) async {
  try {
    return await launcher.launchUrl(uri, mode: launcher.LaunchMode.externalApplication, webOnlyWindowName: '_blank');
  } catch (_) {
    return false;
  }
}

/// The link opener; tests replace it (and reset it with
/// [resetQuartettLinkOpener]).
@visibleForTesting
QuartettLinkOpener quartettLinkOpener = _launch;

@visibleForTesting
void resetQuartettLinkOpener() => quartettLinkOpener = _launch;

/// Opens [url] and shows a snack bar if that fails.
Future<void> openQuartettLink(BuildContext context, String url) async {
  final messenger = ScaffoldMessenger.maybeOf(context);
  final failed = AppLocalizations.of(context).quartettLinkFailed;
  final ok = await quartettLinkOpener(Uri.parse(url));
  if (!ok) messenger?.showSnackBar(SnackBar(content: Text(failed)));
}

/// The photo band of a card: the whole photo (contain) over a blurred,
/// cropped copy of itself, so tall rockets and wide planes both fill the
/// band without being cut. Decorative for screen readers (the card name is
/// read). [onInfo] adds the small "ⓘ" credit button.
class QuartettCardPhoto extends StatelessWidget {
  final QuartettImageCredit credit;
  final double height;
  final VoidCallback? onInfo;
  const QuartettCardPhoto({super.key, required this.credit, required this.height, this.onInfo});

  @override
  Widget build(BuildContext context) {
    final l10n = AppLocalizations.of(context);
    Widget image(BoxFit fit) =>
        Image.asset(credit.asset, fit: fit, gaplessPlayback: true, errorBuilder: (_, _, _) => const SizedBox.shrink());
    final info = onInfo;
    return SizedBox(
      height: height,
      child: Stack(
        fit: StackFit.expand,
        children: [
          ExcludeSemantics(
            child: ColoredBox(
              color: Colors.black,
              child: ClipRect(
                child: ImageFiltered(
                  imageFilter: ImageFilter.blur(sigmaX: 14, sigmaY: 14, tileMode: TileMode.clamp),
                  child: Opacity(opacity: 0.6, child: image(BoxFit.cover)),
                ),
              ),
            ),
          ),
          ExcludeSemantics(child: image(BoxFit.contain)),
          if (info != null)
            PositionedDirectional(
              end: 4,
              bottom: 4,
              child: Material(
                color: Colors.black54,
                shape: const CircleBorder(),
                clipBehavior: Clip.antiAlias,
                child: IconButton(
                  key: const Key('quartett-photo-info'),
                  tooltip: l10n.quartettPhotoCreditTooltip,
                  visualDensity: VisualDensity.compact,
                  iconSize: 20,
                  color: Colors.white,
                  onPressed: info,
                  icon: const Icon(Icons.info_outline),
                ),
              ),
            ),
        ],
      ),
    );
  }
}

/// The credit line `Foto: <Autor>, <Lizenz>`.
String quartettCreditLine(AppLocalizations l10n, QuartettImageCredit c) =>
    l10n.quartettPhotoCredit(c.author, c.license);

/// Shows the credit of a card photo with links to the licence and source.
Future<void> showQuartettPhotoCredit(BuildContext context, QuartettImageCredit credit) {
  return showDialog<void>(
    context: context,
    builder: (ctx) {
      final l10n = AppLocalizations.of(ctx);
      final theme = Theme.of(ctx);
      return AlertDialog(
        key: const Key('quartett-photo-credit'),
        title: Text(l10n.quartettPhotoCreditTitle),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(quartettCreditLine(l10n, credit), key: const Key('quartett-photo-credit-line')),
              const SizedBox(height: 8),
              Text(
                credit.shareAlike
                    ? '${l10n.quartettPhotoModified} ${l10n.quartettPhotoShareAlike}'
                    : l10n.quartettPhotoModified,
                style: theme.textTheme.bodySmall,
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
            key: const Key('quartett-photo-license'),
            onPressed: () => openQuartettLink(ctx, credit.licenseUrl),
            child: Text(l10n.quartettPhotoLicense),
          ),
          TextButton(
            key: const Key('quartett-photo-source'),
            onPressed: () => openQuartettLink(ctx, credit.source),
            child: Text(l10n.quartettPhotoSource),
          ),
          TextButton(
            key: const Key('quartett-photo-close'),
            onPressed: () => Navigator.of(ctx).pop(),
            child: Text(l10n.quartettPhotoClose),
          ),
        ],
      );
    },
  );
}

/// "Auf Wikipedia lesen" for [media] in the current UI language (nothing if
/// the card has no article).
class QuartettWikipediaButton extends StatelessWidget {
  final QuartettCardMedia? media;
  const QuartettWikipediaButton({super.key, required this.media});

  @override
  Widget build(BuildContext context) {
    final url = media?.wikipediaUrl(Localizations.localeOf(context).languageCode);
    if (url == null) return const SizedBox.shrink();
    return TextButton.icon(
      key: const Key('quartett-wikipedia'),
      onPressed: () => openQuartettLink(context, url),
      icon: const Icon(Icons.open_in_new, size: 18),
      label: Text(AppLocalizations.of(context).quartettWikipediaRead),
    );
  }
}

/// "Bildnachweise": the credits of every bundled card photo, per deck
/// ([deck] = only that deck). Reachable from the card gallery.
class QuartettImageCreditsScreen extends StatelessWidget {
  final String? deck;
  const QuartettImageCreditsScreen({super.key, this.deck});

  @override
  Widget build(BuildContext context) {
    final l10n = AppLocalizations.of(context);
    final theme = Theme.of(context);
    final decks = [
      for (final d in qe.QuartettDeck.all)
        if ((deck == null || d.id == deck) && (quartettMediaData[d.id]?.values.any((m) => m.image != null) ?? false)) d,
    ];
    return Scaffold(
      appBar: AppBar(title: Text(l10n.quartettImageCreditsTitle)),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 720),
            // Not lazy: one tile per photo (32 per deck), all built (tests,
            // screen readers), like the card gallery.
            child: SingleChildScrollView(
              key: const Key('quartett-image-credits'),
              padding: const EdgeInsets.symmetric(vertical: 8),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Padding(
                    padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
                    child: Text(l10n.quartettImageCreditsIntro, style: theme.textTheme.bodyMedium),
                  ),
                  for (final d in decks)
                    for (final card in d.cards)
                      if (quartettMediaOf(card)?.image case final img?)
                        ListTile(
                          key: Key('quartett-credit-${d.id}-${card.id}'),
                          leading: ClipRRect(
                            borderRadius: BorderRadius.circular(6),
                            child: ExcludeSemantics(
                              child: Image.asset(
                                img.asset,
                                width: 48,
                                height: 48,
                                fit: BoxFit.cover,
                                errorBuilder: (_, _, _) => const SizedBox(width: 48, height: 48),
                              ),
                            ),
                          ),
                          title: Text('${card.id} ${card.name}'),
                          subtitle: Text(quartettCreditLine(l10n, img)),
                          trailing: Icon(Icons.info_outline, color: theme.colorScheme.onSurfaceVariant),
                          onTap: () => showQuartettPhotoCredit(context, img),
                        ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}
